"""Acionamento do pipeline: subprocess do headless + import do assemble_n5 (HANDOFF §1.2).

O portal NUNCA importa PySide6 nem o motor SA. As etapas 2-4 rodam por SUBPROCESS do
CLI existente `scripts.arete.headless_sa_analise` (Qt offscreen isolado num processo
filho — se estourar RAM/travar, nao derruba o web server). A etapa 6 (N5) importa
`src.core.n5_assembler.assemble_n5` diretamente (leve, so ezdxf).

`dry_run=True` (default nos testes) NAO dispara subprocess — retorna o comando que
seria executado. O codigo de producao chama de verdade (dry_run=False).
"""

from __future__ import annotations

import logging
import subprocess
import sys
from dataclasses import dataclass, field
from pathlib import Path
from typing import Optional

from .config import Settings

log = logging.getLogger("portal.pipeline_runner")

# Etapas que o portal aciona (HANDOFF §1.2). 'validacao' nao passa por aqui (so DB).
ETAPAS_SUBPROCESS = ("triagem", "recortes", "sa")
ETAPAS_TODAS = ("triagem", "recortes", "sa", "n5")


@dataclass
class ResultadoEtapa:
    etapa: str
    ok: bool
    comando: list[str] = field(default_factory=list)
    returncode: Optional[int] = None
    log_tail: str = ""
    artefatos: dict = field(default_factory=dict)
    dry_run: bool = False


def engine_version(repo_root: Path) -> str:
    """git rev-parse --short HEAD -> 'git-<sha>' (P5 reprodutibilidade). Fail-safe: 'git-unknown'."""
    try:
        out = subprocess.run(
            ["git", "rev-parse", "--short", "HEAD"],
            cwd=str(repo_root), capture_output=True, text=True, timeout=10,
        )
        if out.returncode == 0 and out.stdout.strip():
            return f"git-{out.stdout.strip()}"
    except (OSError, subprocess.SubprocessError):
        pass
    return "git-unknown"


def _obra_dir(settings: Settings, obra: dict) -> Path:
    """Diretorio de trabalho da obra (onde o headless procura --obra).

    Usa local_path se o poller o gravou; senao cai no layout DADOS-OBRAS/<nome>.
    """
    lp = obra.get("local_path")
    if lp:
        return Path(lp)
    return settings.dados_obras_dir / obra.get("nome", "obra")


def montar_comando_headless(
    settings: Settings,
    obra: dict,
    *,
    secao: Optional[list[str]] = None,
    pav: Optional[str] = None,
) -> list[str]:
    """Comando do headless para as etapas de recortes/sa (HANDOFF §1.2).

    Sempre usa --wait (automacao): serializa contra QUALQUER headless da maquina via
    o single_instance lock, inclusive os disparados pela app PySide6 do dono (§3.1).
    """
    obra_dir = _obra_dir(settings, obra)
    cmd = [
        sys.executable, "-m", "scripts.arete.headless_sa_analise",
        "--obra", str(obra_dir),
        "--pav", pav or settings.pav_default,
        "--wait",
    ]
    for s in secao or []:
        cmd += ["--secao", s]
    return cmd


def _tail(texto: str, linhas: int = 40) -> str:
    return "\n".join((texto or "").splitlines()[-linhas:])


def executar_etapa(
    settings: Settings,
    etapa: str,
    obra: dict,
    *,
    secao: Optional[list[str]] = None,
    pav: Optional[str] = None,
    dry_run: bool = True,
    log_path: Optional[Path] = None,
) -> ResultadoEtapa:
    """Executa uma etapa de pipeline (triagem/recortes/sa) via subprocess.

    N5 NAO passa por aqui — usa executar_n5(). validacao NAO passa por aqui — so DB.
    dry_run=True devolve o comando sem disparar (default seguro para testes).
    """
    if etapa not in ETAPAS_SUBPROCESS:
        raise ValueError(f"etapa {etapa!r} nao e' de subprocess (validas: {ETAPAS_SUBPROCESS})")

    # triagem e recortes usam o mesmo CLI (fases anteriores do pipeline); MVP dispara
    # o headless que ja encadeia as fases. --secao restringe classe quando informado.
    cmd = montar_comando_headless(settings, obra, secao=secao, pav=pav)

    if dry_run:
        return ResultadoEtapa(etapa=etapa, ok=True, comando=cmd, dry_run=True)

    try:
        proc = subprocess.run(
            cmd, cwd=str(settings.repo_root), capture_output=True, text=True,
            timeout=settings.subprocess_timeout_s,
        )
    except subprocess.TimeoutExpired:
        return ResultadoEtapa(etapa=etapa, ok=False, comando=cmd, returncode=None,
                              log_tail="timeout do subprocess")
    except OSError as exc:
        return ResultadoEtapa(etapa=etapa, ok=False, comando=cmd, returncode=None,
                              log_tail=f"erro ao iniciar subprocess: {exc}")

    saida = (proc.stdout or "") + "\n" + (proc.stderr or "")
    if log_path is not None:
        try:
            Path(log_path).parent.mkdir(parents=True, exist_ok=True)
            Path(log_path).write_text(saida, encoding="utf-8", errors="replace")
        except OSError:
            pass

    obra_dir = _obra_dir(settings, obra)
    artefatos = {
        "obra_dir": str(obra_dir),
        "fase6_dir": str(obra_dir / "Fase-6_Execucao_CAD"),
    }
    return ResultadoEtapa(
        etapa=etapa, ok=(proc.returncode == 0), comando=cmd,
        returncode=proc.returncode, log_tail=_tail(saida), artefatos=artefatos,
    )


def executar_n5(
    settings: Settings,
    obra: dict,
    *,
    classe: str,
    pavimento: str = "GERAL",
    dry_run: bool = True,
) -> ResultadoEtapa:
    """Etapa 6: chama assemble_n5 (import direto, leve). Gera 1 DXF por classe+pav.

    dry_run=True nao importa nem escreve — so descreve a chamada.
    """
    obra_dir = _obra_dir(settings, obra)
    if dry_run:
        return ResultadoEtapa(
            etapa="n5", ok=True, dry_run=True,
            comando=["assemble_n5", str(obra_dir), classe, f"pavimento={pavimento}"],
        )
    try:
        from src.core.n5_assembler import assemble_n5  # import tardio: isola ezdxf
    except ImportError as exc:
        return ResultadoEtapa(etapa="n5", ok=False, log_tail=f"import assemble_n5 falhou: {exc}")

    try:
        resultado = assemble_n5(obra_dir, classe, pavimento=pavimento)
    except Exception as exc:  # noqa: BLE001 - erro do assembler vira estado de job 'error'
        return ResultadoEtapa(etapa="n5", ok=False,
                              comando=["assemble_n5", str(obra_dir), classe],
                              log_tail=f"assemble_n5 erro: {exc}")

    dxf_path = str(resultado.output_path)
    artefatos = {
        "n5_dxf": dxf_path,
        "n5_manifest": str(resultado.manifest_path),
        "ok_count": resultado.ok_count,
        "missing_count": resultado.missing_count,
    }
    ok = resultado.ok_count > 0
    return ResultadoEtapa(etapa="n5", ok=ok, comando=["assemble_n5", str(obra_dir), classe],
                          returncode=0 if ok else 1, artefatos=artefatos)

"""Rotas de autenticacao: POST /login, POST /logout, GET /me (HANDOFF §1.1/§4)."""

from __future__ import annotations

from fastapi import APIRouter, Depends, HTTPException, Request, Response, status
from pydantic import BaseModel

from .. import auth

router = APIRouter(tags=["auth"])


class LoginIn(BaseModel):
    login: str
    senha: str


class MembroOut(BaseModel):
    login: str
    nome: str
    papel: str


@router.post("/login")
def login(body: LoginIn, request: Request, response: Response):
    settings = request.app.state.settings
    conn = request.app.state.db
    membro = auth.autenticar(conn, body.login, body.senha)
    if membro is None:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED, detail="login ou senha invalidos"
        )
    cookie = auth.emitir_cookie(settings, membro["login"])
    response.set_cookie(
        key=settings.session_cookie_name,
        value=cookie,
        httponly=True,
        samesite="lax",
        secure=settings.cookie_secure,
        max_age=settings.session_ttl_horas * 3600,
    )
    return {"ok": True, "membro": {
        "login": membro["login"], "nome": membro["nome"], "papel": membro["papel"],
    }}


@router.post("/logout")
def logout(request: Request, response: Response):
    settings = request.app.state.settings
    response.delete_cookie(settings.session_cookie_name)
    return {"ok": True}


@router.get("/me", response_model=MembroOut)
def me(membro: dict = Depends(auth.exige_login)):
    return MembroOut(login=membro["login"], nome=membro["nome"], papel=membro["papel"])

"""Rotas de obras: GET /obras, GET /obras/{id} (HANDOFF §1.1/§1.2 etapa 1)."""

from __future__ import annotations

from fastapi import APIRouter, Depends, HTTPException, Request

from .. import auth, certification
from ..db import repository as repo

router = APIRouter(prefix="/obras", tags=["obras"])


@router.get("")
def listar_obras(request: Request, membro: dict = Depends(auth.exige_login)):
    """Etapa 1 (Upload): lista as obras do membro detectadas pelo poller."""
    conn = request.app.state.db
    obras = repo.listar_obras_por_membro(conn, membro["id"])
    return {
        "membro": membro["login"],
        "drive": request.app.state.estado_global.get("drive", "ok"),
        "obras": obras,
    }


@router.get("/{obra_id}")
def obter_obra(obra_id: str, request: Request, membro: dict = Depends(auth.exige_login)):
    conn = request.app.state.db
    obra = repo.obter_obra(conn, obra_id)
    if obra is None:
        raise HTTPException(status_code=404, detail="obra nao encontrada")
    if obra["membro_id"] != membro["id"]:
        raise HTTPException(status_code=403, detail="obra de outro membro")
    settings = request.app.state.settings
    jobs = repo.listar_jobs_por_obra(conn, obra_id)
    releases = repo.listar_n5_releases_por_obra(conn, obra_id)
    comentarios = repo.listar_comentarios_por_obra(conn, obra_id)
    # rotulos de certificacao por classe (R9) — exibidos junto da obra
    rotulos = {
        c: certification.classificar_certificacao(settings.status_md_path, c)
        for c in ("PL", "LV", "FV", "LJ")
    }
    return {
        "obra": obra,
        "jobs": jobs,
        "n5_releases": releases,
        "comentarios": comentarios,
        "rotulos_certificacao": rotulos,
    }

"""Rotas de fichas HTML: serve os HTML N1-N4 ja gerados pelo pipeline (HANDOFF §1.1).

O portal SO LE estes artefatos (regra de fronteira §3) — nunca escreve neles. As
fichas ficam em <obra_dir>/Fase-6_Execucao_CAD/. O portal lista e serve o HTML como
estatico, com protecao de path traversal (nunca sai do diretorio da obra).
"""

from __future__ import annotations

from pathlib import Path

from fastapi import APIRouter, Depends, HTTPException, Request
from fastapi.responses import FileResponse

from .. import auth
from ..db import repository as repo

router = APIRouter(prefix="/obras", tags=["fichas"])


def _obra_dir(request: Request, obra: dict) -> Path:
    settings = request.app.state.settings
    lp = obra.get("local_path")
    return Path(lp) if lp else settings.dados_obras_dir / obra.get("nome", "obra")


def _obra_do_membro(request: Request, obra_id: str, membro: dict) -> dict:
    conn = request.app.state.db
    obra = repo.obter_obra(conn, obra_id)
    if obra is None:
        raise HTTPException(status_code=404, detail="obra nao encontrada")
    if obra["membro_id"] != membro["id"]:
        raise HTTPException(status_code=403, detail="obra de outro membro")
    return obra


@router.get("/{obra_id}/fichas")
def listar_fichas(obra_id: str, request: Request, membro: dict = Depends(auth.exige_login)):
    """Lista os HTML de ficha disponiveis para a obra (viewer basico)."""
    obra = _obra_do_membro(request, obra_id, membro)
    base = _obra_dir(request, obra) / "Fase-6_Execucao_CAD"
    fichas = []
    if base.exists():
        for p in sorted(base.rglob("*.html")):
            fichas.append({
                "nome": p.name,
                "rel": str(p.relative_to(base)).replace("\\", "/"),
                "tamanho": p.stat().st_size,
            })
    return {"obra_id": obra_id, "total": len(fichas), "fichas": fichas}


@router.get("/{obra_id}/fichas/{rel_path:path}")
def servir_ficha(obra_id: str, rel_path: str, request: Request,
                 membro: dict = Depends(auth.exige_login)):
    """Serve um HTML de ficha especifico (com guarda contra path traversal)."""
    obra = _obra_do_membro(request, obra_id, membro)
    base = (_obra_dir(request, obra) / "Fase-6_Execucao_CAD").resolve()
    alvo = (base / rel_path).resolve()
    # guarda: alvo tem que estar DENTRO de base (nunca sobe com ../)
    if base not in alvo.parents and alvo != base:
        raise HTTPException(status_code=403, detail="path fora da obra")
    if not alvo.exists() or not alvo.is_file():
        raise HTTPException(status_code=404, detail="ficha nao encontrada")
    if alvo.suffix.lower() not in (".html", ".htm", ".svg", ".css", ".js", ".png", ".json"):
        raise HTTPException(status_code=415, detail="tipo de arquivo nao servivel")
    return FileResponse(str(alvo))

